import {defaults,simulate,unitCosts,idealDoubling} from './model.js';
const es=document.documentElement.lang==='es',t=(a,b)=>es?a:b,$=s=>document.querySelector(s),nf=new Intl.NumberFormat(es?'es-ES':'en-US',{maximumFractionDigits:1}),fmt=x=>nf.format(x),p={...defaults};let day=0,rows=simulate(p),timer=null,metric=0;
const range=(id,label,min,max,step,value,suffix='')=>`<label for="${id}">${label}<output id="${id}-value">${value}${suffix}</output><input id="${id}" type="range" min="${min}" max="${max}" step="${step}" value="${value}"></label>`;
$('#app').innerHTML=`<nav><b>r. ROBOT LAB</b><a href="../index.html">Atlas</a><a href="../robots/factory.html">${t('Fábrica 3D','3D factory')}</a><a href="../terafab/index.html">Terafab</a><a href="../dyson/index.html">${t('Dyson','Dyson')}</a><a href="../home/index.html">${t('Hogar','Home')}</a><a href="${es?'../../growth/index.html':'../es/growth/index.html'}">${es?'EN':'ES'}</a></nav><h1>${t('Cuando lo que produces<br>también puede producir.','When what you make<br>can also make things.')}</h1><p class="intro">${t('Más horas aumentan la producción. Reinvertir en nuevos robots multiplica los productores: ahí empieza el crecimiento exponencial.','More working hours increase output. Reinvesting in new robots multiplies the producers: this is where exponential growth starts.')}</p>
<section class="workbench"><div class="plot"><div class="plot-top"><span class="eyebrow">${t('TRES ESCENARIOS · MISMA TAREA','THREE SCENARIOS · SAME TASK')}</span><button id="metric">${t('Ver bienes disponibles / día','Show available goods / day')}</button></div><div class="legend"><span>━ ${t('Trabajo humano','Human work')}</span><span>━ ${t('10 robots, sin reinversión','10 robots, no reinvestment')}</span><span>━ ${t('Robots con reinversión','Robots with reinvestment')}</span></div><p class="chart-unit" id="chart-unit"></p><svg class="chart" id="chart" role="img"></svg><div class="timeline"><button id="play">▶ ${t('Reproducir','Play')}</button><input type="range" min="0" max="90" value="0" id="day" aria-label="${t('Día simulado','Simulated day')}"><span id="day-label"></span><button id="restart" aria-label="${t('Volver al inicio','Restart')}">↺</button></div><div class="metrics" aria-live="polite"><article><small>${t('Humanos','Humans')}</small><strong id="human"></strong><span id="human-note"></span></article><article><small>${t('Robots fijos','Fixed robot fleet')}</small><strong id="fixed"></strong><span>${t('10 robots · no crece la flota','10 robots · fleet does not grow')}</span></article><article><small>${t('Con reinversión','With reinvestment')}</small><strong id="growing"></strong><span id="growing-note"></span></article></div><p id="verdict" class="verdict"></p><p class="doubling-events" id="doubling-events"></p><div id="fleet" class="fleet" aria-hidden="true"></div><p id="fleet-note" class="note"></p><p class="note">${t('Una unidad es un bien genérico que requiere una hora efectiva de trabajo. Humanos y robots tienen el mismo ritmo por hora. Los robots nuevos tardan dos días completos en incorporarse tras su fabricación.','One unit is a generic good requiring one effective working hour. Humans and robots have the same hourly pace. New robots take two full days to join after production.')}</p><details><summary>${t('Ver los valores de las curvas','Read chart values')}</summary><div class="table-wrap"><table><thead><tr><th>${t('Día','Day')}</th><th>${t('Humanos','Humans')}</th><th>${t('Robots fijos','Fixed robots')}</th><th>${t('Reinversión','Reinvestment')}</th></tr></thead><tbody id="table"></tbody></table></div></details></div>
<aside class="controls">${range('hours',t('Horas por robot / día','Hours per robot / day'),8,24,1,21)}${range('reinvest',t('Trabajo para crear robots','Work to create robots'),0,100,5,70,'%')}${range('buildHours',t('Horas de trabajo / robot nuevo','Working hours / new robot'),120,960,60,240)}<label>${t('Turnos humanos de 8 h','8-hour human shifts')}<select id="shifts"><option value="1">${t('1 turno · 10 personas','1 shift · 10 people')}</option><option value="2">${t('2 turnos · 20 personas','2 shifts · 20 people')}</option><option value="3">${t('3 turnos · 30 personas','3 shifts · 30 people')}</option></select></label><label class="check"><input type="checkbox" id="limited" checked>${t('Aplicar límites de instalaciones y materiales','Apply facility and material limits')}</label>${range('slots',t('Plazas de robot instaladas','Installed robot slots'),10,200,10,100)}${range('supply',t('Suministro: unidades equivalentes / día','Supply: equivalent units / day'),100,4000,100,1500)}<p class="note">${t('Todos los números son supuestos educativos. Las plazas solo limitan cuántos robots pueden existir; no recortan las horas de los turnos humanos. Los turnos humanos no modelan cobertura de descansos semanales. El suministro limita horas equivalentes de trabajo, también al fabricar robots. 21 h descuenta paradas; 24 h es un máximo ideal. Una planta humana también puede operar día y noche mediante turnos.','All numbers are teaching assumptions. Slots only limit how many robots can exist; they do not cut human-shift hours. Human shifts do not model weekly-rest coverage. Supply limits equivalent working hours, including robot production. 21 h allows for downtime; 24 h is an ideal maximum. A human-staffed plant can also operate around the clock using shifts.')}</p></aside></section>
<section class="principles"><article class="principle"><span class="eyebrow">01 · ${t('MÁS HORAS','MORE HOURS')}</span><b id="hours-factor"></b><p>${t('Es una ventaja fija por trabajador, antes de restricciones. Por sí sola no produce crecimiento exponencial.','This is a fixed per-worker advantage, before constraints. On its own it does not produce exponential growth.')}</p></article><article class="principle"><span class="eyebrow">02 · ${t('MÁS PRODUCTORES','MORE PRODUCERS')}</span><b id="doubling"></b><p>${t('Duplicación matemática ideal, sin esperas ni límites y con capacidad divisible. La simulación superior incorpora robots enteros y espera de puesta en marcha.','Ideal mathematical doubling, with no delays or limits and divisible capacity. The simulation above uses whole robots and commissioning delays.')}</p></article><article class="principle"><span class="eyebrow">03 · ${t('EL FRENO REAL','THE REAL CONSTRAINT')}</span><b>${t('Materiales + máquinas','Materials + machines')}</b><p>${t('Reinvertir resta bienes disponibles hoy. La capacidad nueva necesita instalaciones, piezas, energía e integración; no aparece gratis ni se expande sola.','Reinvestment reduces goods available today. New capacity needs facilities, parts, energy and integration; it is neither free nor self-expanding.')}</p></article></section>
<section class="cost"><span class="eyebrow">${t('COSTE POR UNIDAD · OTRO EXPERIMENTO','COST PER UNIT · A SEPARATE EXPERIMENT')}</span><h2>${t('Más barato no significa gratis.','Cheaper does not mean free.')}</h2><p>${t('Comparación de una tarea ya automatizable, a una unidad por hora activa y utilizando toda la capacidad. Son valores de ejemplo editables, no precios de Optimus ni presupuestos de Terafab. No se usan para financiar la simulación superior.','Comparison for an already automatable task, at one unit per active hour and full utilization. These are editable example values, not Optimus prices or Terafab budgets. They do not finance the simulation above.')}</p><div class="cost-grid" id="cost-inputs"></div><div class="cost-result"><div><span>${t('Trabajo humano + material','Human work + material')}</span><strong id="human-cost"></strong></div><div><span>${t('Robot + material','Robot + material')}</span><strong id="robot-cost"></strong></div><div><span>${t('Diferencia con estos supuestos','Difference under these assumptions')}</span><strong id="saving"></strong></div></div><details><summary>${t('Qué incluye el cálculo y qué falta','What is included and what is missing')}</summary><p id="formula"></p><p>${t('La instalación se reparte linealmente entre años × 365 días, sin valor residual. La supervisión se expresa por robot y día. Se mantienen iguales material y calidad. Faltan financiación, impuestos, costes comunes de edificio y máquinas, rechazos y cambios de proceso; no es el coste total de una fábrica. Menor utilización aumenta el coste por unidad.','Installed cost is spread linearly across years × 365 days, with no residual value. Supervision is per robot per day. Material and quality are held equal. Financing, tax, shared building and machine costs, rejects and process changes are omitted; this is not total factory cost. Lower utilization increases unit cost.')}</p><a target="_blank" rel="noreferrer" href="https://www.universal-robots.com/blog/calculating-roi-and-payback-period-for-your-robotic-investment/">Universal Robots · ${t('integración, accesorios y mantenimiento en el coste','integration, accessories and maintenance in cost')} ↗</a></details></section>
<section class="home-link"><span class="eyebrow">${t('OTRAS ESCALAS','OTHER SCALES')}</span><h2>${t('De la casa a la estrella.','From the home to the star.')}</h2><p>${t('El hogar cuenta minutos recuperados. La esfera de Dyson cuenta la energía de una estrella. Ninguno de los dos es una previsión de fechas.','The home counts reclaimed minutes. The Dyson sphere counts a star’s energy. Neither is a dated forecast.')}</p><a href="../home/index.html">${t('Explorar el hogar →','Explore the home →')}</a> <a href="../dyson/index.html">${t('Esfera de Dyson →','Dyson sphere →')}</a></section><div class="explore">${[['factory','Fábrica','Factory'],['district','Distrito','District'],['city','Ciudad','City'],['region','Región','Region']].map(([id,a,b])=>`<a href="../robots/${id}.html">${t(a,b)} 3D ↗</a>`).join('')}<a href="../starlink/index.html">Starlink ↗</a><a href="../spacex/index.html">SpaceX ↗</a></div><footer>${t('Modelo didáctico independiente. No demuestra que una cadena industrial completa pueda reproducirse de forma autónoma. Los días son unidades del ejemplo, no una previsión de adopción.','Independent teaching model. It does not establish that an entire industrial supply chain can reproduce autonomously. Days are example units, not an adoption forecast.')}</footer>`;
function costs(){const c=unitCosts(p),money=x=>new Intl.NumberFormat(es?'es-ES':'en-US',{style:'currency',currency:'EUR'}).format(x);$('#human-cost').textContent=money(c.human);$('#robot-cost').textContent=money(c.robot);const delta=c.human-c.robot;$('#saving').textContent=money(delta)+' · '+fmt(100*delta/c.human)+'%';$('#saving').parentElement.querySelector('span').textContent=delta>=0?t('Ahorro por unidad','Saving per unit'):t('El robot sale más caro','The robot costs more');$('#formula').textContent=t('Humano = material + coste laboral por hora. Robot = material + [instalación / (vida × 365) + servicio anual / 365 + supervisión diaria + kW × €/kWh × horas] / horas.','Human = material + hourly labor cost. Robot = material + [installed cost / (life × 365) + yearly service / 365 + daily supervision + kW × €/kWh × hours] / hours.');}
const costFields=[['wage','Coste laboral completo €/h','Fully loaded labor €/h',1,200,1],['installed','Robot instalado €','Installed robot €',1000,500000,1000],['life','Vida útil, años','Useful life, years',1,20,1],['service','Servicio y software €/año','Service and software €/year',0,100000,100],['power','Consumo activo, kW','Active power, kW',0,50,.1],['energy','Electricidad €/kWh','Electricity €/kWh',0,2,.01],['supervision','Supervisión €/día','Supervision €/day',0,1000,1],['material','Material por unidad €','Material per unit €',0,1000,1]];
$('#cost-inputs').innerHTML=costFields.map(([id,a,b,min,max,step])=>`<label for="cost-${id}">${t(a,b)}<input id="cost-${id}" type="number" min="${min}" max="${max}" step="${step}" value="${p[id]}"></label>`).join('');costFields.forEach(([id,a,b,min,max])=>$('#cost-'+id).addEventListener('input',e=>{if(e.target.value===''||!e.target.checkValidity())return;p[id]=Math.max(min,Math.min(max,Number(e.target.value)));costs();}));
function draw(){const r=rows[day],cumulative=metric===2,unit=metric===0?t('capacidad utilizada · unidades equivalentes / día','utilized capacity · equivalent units / day'):t(cumulative?'bienes acumulados hasta hoy':'bienes disponibles / día',cumulative?'cumulative goods through today':'available goods / day');$('#chart-unit').textContent=unit+' · '+t('90 días del ejemplo','90 example days')+(metric===0?t('. Incluye bienes y trabajo para crear robots.','. Includes goods and work to create robots.'):cumulative?t('. Incluye la producción del día visible.','. Includes the visible day’s output.'):'');$('#day-label').textContent=t('Día ','Day ')+day;$('#day').value=day;$('#human').textContent=fmt(cumulative?r.humanToDate:r.human);$('#fixed').textContent=fmt(cumulative?r.fixedToDate:r.fixed);$('#growing').textContent=fmt(cumulative?r.goodsToDate:metric===0?r.work:r.output);$('#human-note').textContent=`${10*p.shifts} ${t('personas en','people in')} ${p.shifts} ${t('turno(s)','shift(s)')} · ${unit}`;$('#growing-note').textContent=`${fmt(r.fleet)} ${t('robots activos','active robots')} · ${unit}`;
 const compared=cumulative?r.goodsToDate/r.humanToDate:metric===0?r.work/r.human:r.output/r.human,ratio=r.human>0?compared:0,ratioLabel=metric===0?t('la capacidad humana utilizada. ','human utilized capacity. '):t('la producción humana en bienes. ','human goods output. ');
 const slotsFull=p.limited&&r.fleet>=p.slots,brake=r.limited&&slotsFull?t('El suministro limita las horas y las plazas están llenas.','Supply is limiting hours and all slots are occupied.'):r.limited?t('El suministro limita las horas equivalentes.','Supply is limiting equivalent hours.'):slotsFull?t('Las plazas están llenas: la flota deja de crecer.','All slots are occupied: the fleet stops growing.'):p.reinvest===0?t('Sin reinversión, la flota se mantiene constante.','Without reinvestment the fleet remains constant.'):t('Parte del trabajo se dedica a construir capacidad futura.','Some work is allocated to building future capacity.');
 $('#verdict').textContent=`${t('Hoy: ','Today: ')}${fmt(ratio)}× ${ratioLabel}${brake}`;
 const milestones=[20,40,80,160,320].map(n=>({n,row:rows.find(r=>r.fleet>=n)})).filter(m=>m.row);$('#doubling-events').textContent=t('Duplicaciones de la flota: 10 iniciales','Fleet doublings: 10 initially')+milestones.map(m=>' → '+m.n+' ('+t('día ','day ')+m.row.day+')').join('')+(milestones.length?'':t(' · aún sin duplicar en 90 días.',' · no doubling within 90 days.'));
 $('#fleet').innerHTML=Array.from({length:Math.min(200,r.fleet)},(_,i)=>`<i class="${i<10?'seed':''}"></i>`).join('');$('#fleet-note').textContent=`${t('10 robots iniciales','10 starting robots')} + ${r.fleet-10} ${t('incorporados','deployed')} · ${r.pending} ${t('en puesta en marcha','commissioning')} · ${fmt(r.buildWork)} ${t('h hoy para construir robots','h today building robots')}. ${r.fleet>200?t('Se dibujan los primeros 200.','First 200 shown.'):t('Un cuadrado = un robot.','One square = one robot.')}`;
 const series=cumulative?['humanToDate','fixedToDate','goodsToDate']:['human','fixed',metric===0?'work':'output'],colors=['#efb38e','#9cbeef','#a7e0cf'],width=Math.max(320,$('#chart').clientWidth),height=300,left=60,right=width-20,top=25,bottom=255,max=Math.max(1,...rows.flatMap(x=>series.map(k=>x[k]))),x=d=>left+d/90*(right-left),y=v=>bottom-v/max*(bottom-top);let svg='';
 for(let i=0;i<=4;i++){const v=max*i/4,yy=y(v);svg+=`<path d="M${left} ${yy}H${right}" stroke="#73879733"/><text x="${left-8}" y="${yy+5}" text-anchor="end" fill="#aec4d3" font-size="12">${new Intl.NumberFormat(es?'es':'en',{notation:'compact',maximumFractionDigits:1}).format(v)}</text>`;}
 for(const d of [0,30,60,90])svg+=`<text x="${x(d)}" y="280" text-anchor="middle" fill="#aec4d3" font-size="13">${d}</text>`;
 series.forEach((k,i)=>{const points=rows.map(r=>`${x(r.day)},${y(r[k])}`).join(' ');svg+=`<polyline points="${points}" fill="none" stroke="${colors[i]}" stroke-width="3" ${i===0?'stroke-dasharray="7 4"':''}/>`;});svg+=`<path d="M${x(day)} ${top}V${bottom}" stroke="#ffffffaa" stroke-dasharray="3 4"/>`;series.forEach((k,i)=>svg+=`<circle cx="${x(day)}" cy="${y(r[k])}" r="5" fill="${colors[i]}"/>`);$('#chart').setAttribute('viewBox',`0 0 ${width} ${height}`);$('#chart').innerHTML=svg;$('#chart').setAttribute('aria-label',unit+t(' frente a días. Los valores están en la tabla siguiente.',' against days. Values are available in the following table.'));
 $('#table').innerHTML=[...new Set([0,15,30,45,60,75,90,day])].sort((a,b)=>a-b).map(d=>`<tr><td>${d}</td>${series.map(k=>`<td>${fmt(rows[d][k])}</td>`).join('')}</tr>`).join('');$('#hours-factor').textContent=fmt(p.hours/8)+'× '+t('por trabajador','per worker');$('#doubling').textContent=Number.isFinite(idealDoubling(p))?fmt(idealDoubling(p))+' '+t('días','days'):t('Sin duplicación','No doubling');}
function update(){rows=simulate(p);draw();costs();}
for(const id of ['hours','reinvest','buildHours','slots','supply'])$('#'+id).addEventListener('input',e=>{p[id]=Number(e.target.value)/(id==='reinvest'?100:1);$('#'+id+'-value').textContent=e.target.value+(id==='reinvest'?'%':'');update();});$('#shifts').onchange=e=>{p.shifts=Number(e.target.value);update();};$('#limited').onchange=e=>{p.limited=e.target.checked;for(const id of ['slots','supply'])$('#'+id).disabled=!p.limited;update();};
function stop(){clearInterval(timer);timer=null;$('#play').textContent='▶ '+t('Reproducir','Play');}$('#play').onclick=()=>{if(timer){stop();return;}if(day===90)day=0;$('#play').textContent='Ⅱ '+t('Pausar','Pause');timer=setInterval(()=>{if(document.hidden)return;day=Math.min(90,day+1);draw();if(day===90)stop();},200);};$('#day').oninput=e=>{stop();day=+e.target.value;draw();};$('#restart').onclick=()=>{stop();day=0;draw();};$('#metric').onclick=()=>{metric=(metric+1)%3;$('#metric').textContent=metric===0?t('Ver bienes disponibles / día','Show available goods / day'):metric===1?t('Ver bienes acumulados','Show cumulative goods'):t('Ver capacidad utilizada','Show utilized capacity');draw();};new ResizeObserver(draw).observe($('#chart'));
$('#chart').style.cursor='pointer';
$('#chart').onclick=e=>{const r=$('#chart').getBoundingClientRect(),left=60,right=Math.max(320,r.width)-20,x=e.clientX-r.left,d=Math.round(Math.min(90,Math.max(0,(x-left)/(right-left)*90)));stop();day=d;draw();};
update();
